def icon(name): return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+ICON[name]+'</svg>'
def button(label, href, style='primary'): return f'<a class="btn btn-{style}" href="{esc(href)}">{esc(label)}{icon("arrow")}</a>'
def h(text): return text  # Only static, author-controlled title markup enters here.
def rel(lang): return '../' if lang != 'en' else './'
def link(page): return './'+page+'.html'
def section_head(tag,title,desc=''): return f'<div class="section-heading"><div class="stack"><p class="eyebrow">{esc(tag)}</p><h2>{esc(title)}</h2></div>{("<p>"+esc(desc)+"</p>") if desc else ""}</div>'
def dashboard(c):
 cells=''.join(f'<div class="dashboard-cell"><b>{esc(a)}</b>{esc(b)}</div>' for a,b in zip(c['dash_labels'],c['dash_values']))
 return f'<div class="dashboard"><div class="dashboard-title">{esc(c["dashboard"])} <span class="pill">{esc(c["examples"])}</span></div><div class="dashboard-grid">{cells}</div><p class="dashboard-note">{esc(c["dash_note"])}</p></div>'
def hero(c, tag, title, desc, art=False):
 text=f'<div class="hero-copy"><p class="eyebrow">{esc(tag)}</p><h1>{h(title)}</h1><p>{esc(desc)}</p><div class="button-row">{button(c["demo"],link("contact"))}{button(c["explore"],link("commerce"),"outline")}</div></div>'
 if not art: return f'<section class="page-hero"><div class="wrap">{text}</div></section>'
 art_html=f'<div class="hero-art"><img class="hero-photo" src="{ASSET}merchant.webp" alt="" fetchpriority="high"><span class="photo-label">{esc(c["examples"])}</span><div class="floating-card"><div class="card-head"><span>{esc(c["dashboard"])}</span><span class="pill">{esc(c["examples"])}</span></div>'+''.join(f'<div class="mock-row"><span class="mock-icon">{icon(ic)}</span><b>{esc(n)}</b><span>{esc(v)}</span></div>' for ic,n,v in zip(('shop','panel','spark'),c['dash_labels'],c['dash_values']))+'</div></div>'
 return f'<section class="hero"><div class="wrap hero-grid">{text}{art_html}</div></section>'
def cards(names,texts,icons,links=None,c=None):
 return '<div class="cards">'+''.join(f'<article class="card"><div class="card-symbol">{icon(ic)}</div><h3>{esc(name)}</h3><p>{esc(desc)}</p>'+((f'<a class="text-link" href="{esc(link(url))}">{esc(c["view"])} {icon("arrow")}</a>') if links else '')+'</article>' for name,desc,ic,url in zip(names,texts,icons,links or [None]*len(names)))+'</div>'
def steps(c, names='steps', descs='step_text'): return '<div class="steps">'+''.join(f'<article class="step"><span class="step-number">{i:02}</span><h3>{esc(n)}</h3><p>{esc(d)}</p></article>' for i,(n,d) in enumerate(zip(c[names],c[descs]),1))+'</div>'
def cta(c): return f'<section class="section"><div class="wrap"><div class="cta"><div><h2>{esc(c["talk"])}</h2><p>{esc(c["talk_desc"])}</p></div>{button(c["cta"],link("contact"),"light")}</div></div></section>'
def home(c):
 band=''.join(f'<div><strong>{esc(n)}</strong>{esc(d)}</div>' for n,d in zip(c['band'],c['band_desc']))
 audience=''.join(f'<div class="audience"><span>{i:02}</span><b>{esc(n)}</b><p>{esc(d)}</p></div>' for i,(n,d) in enumerate(zip(c['aud_names'],c['aud_text']),1))
 features=''.join('<li>'+esc(x)+'</li>' for x in c['features'])
 return hero(c,c['home_tag'],c['home_title'],c['home_desc'],True)+f'<div class="feature-band"><div class="wrap feature-band-inner"><b>{esc(c["home_band"])}</b><div class="band-items">{band}</div></div></div><section class="section"><div class="wrap split"><div class="visual-panel">{dashboard(c)}</div><div class="stack"><p class="eyebrow">{esc(c["product_tag"])}</p><h2>{esc(c["product_title"])}</h2><p>{esc(c["product_desc"])}</p><ul class="list-check">{features}</ul><div>{button(c["explore"],link("commerce"))}</div></div></div></section><section class="section section-soft"><div class="wrap">{section_head(c["service_tag"],c["service_title"],c["service_desc"])}{cards(c["service_names"],c["service_text"],["shop","code","spark"],["commerce","services","services"],c)}</div></section><section class="section"><div class="wrap">{section_head(c["aud_tag"],c["aud_title"])}<div class="audiences">{audience}</div></div></section>'+cta(c)
def commerce(c):
 return hero(c,c['commerce_tag'],c['commerce_title'],c['commerce_desc'])+f'<section class="section section-soft"><div class="wrap split"><div class="stack"><p class="eyebrow">POMELO COMMERCE</p><h2>{esc(c["commerce_intro"])}</h2><p>{esc(c["commerce_intro_text"])}</p><p class="notice">{esc(c["feature_note"])}</p></div><div class="visual-panel">{dashboard(c)}</div></div></section><section class="section"><div class="wrap">{section_head(c["product_tag"],c["product_title"])}{cards(c["feature_names"],c["feature_text"],["shop","panel","spark"])}</div></section><section class="section section-soft"><div class="wrap">{section_head(c["how_tag"],c["commerce_steps"],c["commerce_steps_desc"])}{steps(c)}<p style="margin-top:2rem">{button(c["nav"][2],link("how-it-works"),"outline")}</p></div></section>'+cta(c)
def how(c):
 items=''.join(f'<article class="journey-item" id="step-{i}"><span class="journey-num">{i:02}</span><div><h2>{esc(n)}</h2><p>{esc(d)}</p></div><div class="journey-art"><div class="dashboard"><div class="card-head"><span>{esc(short)}</span><span class="pill">{esc(c["examples"])}</span></div><div class="mock-row"><span class="mock-icon">{icon(ic)}</span><b>{esc(n)}</b></div><p class="dashboard-note">{esc(c["dash_note"])}</p></div></div></article>' for i,(n,d,short,ic) in enumerate(zip(c['steps'],c['step_text'],c['step_short'],('chat','shop','panel','spark')),1))
 faq=''.join(f'<details class="card"><summary><b>{esc(q)}</b></summary><p>{esc(a)}</p></details>' for q,a in zip(c['faq_q'],c['faq_a']))
 return hero(c,c['how_tag'],c['how_title'],c['how_desc'])+f'<section class="section"><div class="wrap journey">{items}</div></section><section class="section section-soft"><div class="wrap">{section_head("FAQ",c["faq_title"])}<div class="stack">{faq}</div></div></section>'+cta(c)
def services(c): return hero(c,c['services_tag'],c['services_title'],c['services_desc'])+f'<section class="section"><div class="wrap">{section_head(c["services_tag"],c["service_title"])}{cards(c["services_cards"],c["services_copy"],["panel","code","spark"])}</div></section><section class="section section-soft"><div class="wrap">{section_head(c["process_tag"],c["process_title"])}{steps(c,"process_names","process_text")}</div></section>'+cta(c)
def about(c): return hero(c,c['about_tag'],c['about_title'],c['about_desc'])+f'<section class="section section-soft"><div class="wrap split"><div class="stack"><p class="eyebrow">{esc(c["about_tag"])}</p><h2>{esc(c["belief_title"])}</h2><p>{esc(c["belief_text"])}</p><div>{button(c["explore"],link("commerce"),"outline")}</div></div><div class="visual-panel">{dashboard(c)}</div></div></section><section class="section"><div class="wrap"><div class="cards">'+''.join(f'<article class="card"><p class="eyebrow">{esc(k)}</p><h3>{esc(t)}</h3></article>' for k,t in ((c['mission'],c['mission_text']),(c['vision'],c['vision_text']),(c['about_work'],c['about_work_text'])))+f'</div><p class="notice" style="margin-top:1rem">{esc(c["draft_note"])}</p></div></section><section class="section section-soft"><div class="wrap">{section_head(c["process_tag"],c["process_title"])}{steps(c,"process_names","process_text")}</div></section>'+cta(c)
def contact(c):
 fields=''.join(f'<label>{esc(c[key])}<input type="{typ}" name="{key}"></label>' for key,typ in [('name','text'),('shop','text'),('email','email'),('phone','tel')])
 wa='https://wa.me/601139023123'
 follow=''.join(f'<article class="step"><span class="step-number">{i:02}</span><h3>{esc(n)}</h3><p>{esc(d)}</p></article>' for i,(n,d) in enumerate(zip(c['next_names'],c['next_text']),1))
 return hero(c,c['contact_tag'],c['contact_title'],c['contact_desc'])+f'<section class="section section-soft"><div class="wrap contact-layout"><div class="stack"><p class="eyebrow">WHATSAPP</p><h2>{esc(c["whatsapp"])}</h2><p>{esc(c["whatsapp_desc"])}</p><p><strong>+60 11-3902 3123</strong></p><div>{button(c["whatsapp"],wa)}</div></div><div class="contact-card stack"><h2>{esc(c["form_title"])}</h2><p class="notice">{esc(c["form_note"])}</p><form class="form-grid"><fieldset disabled>{fields}<label>{esc(c["interest"])}<select name="interest"><option>Pomelo Commerce</option><option>{esc(c["services_tag"])}</option></select></label><label>{esc(c["message"])}<textarea name="message"></textarea></label><button class="btn btn-primary" type="submit">{esc(c["form_disabled"])}</button></fieldset></form></div></div></section><section class="section"><div class="wrap">{section_head(c["contact_tag"],c["next"])}<div class="steps">{follow}</div></div></section>'+cta(c)
RENDERERS={'index':home,'commerce':commerce,'how-it-works':how,'services':services,'about':about,'contact':contact}
def render(lang,page):
 global ASSET
 c=COPY[lang]; base=rel(lang); ASSET=base+'assets/'
 nav=''.join(f'<a href="{link(p)}"'+(' aria-current="page"' if page==p else '')+f'>{esc(n)}</a>' for p,n in zip(PAGES,c['nav']))
 langs=''.join(f'<a data-locale="{code}" href="{esc(("../" if lang!="en" else "./")+("" if code=="en" else code+"/")+page+".html")}"'+(' aria-current="true"' if code==lang else '')+f'>{esc(name)}</a>' for code,name in [('en','English'),('zh','简体中文'),('ms','Bahasa Melayu')])
 foot=''.join(f'<a href="{link(p)}">{esc(n)}</a>' for p,n in zip(PAGES,c['nav']))
 control=(f'<details class="panel"><summary aria-label="{esc(c["lang"])}" title="{esc(c["lang"])}">{icon("language")}<span class="language-code">{esc(lang.upper())}</span></summary><div class="panel-menu">{langs}</div></details>'
 f'<button class="control" type="button" data-theme-toggle data-dark="{esc(c["dark"])}" data-light="{esc(c["light"])}" aria-label="{esc(c["dark"])}" title="{esc(c["dark"])}">{icon("sun")}</button>'
 f'<details class="panel" data-update data-version="{VERSION}" data-manifest="{base}release.json" data-checking="{esc(c["checking"])}" data-current="{esc(c["current"])}" data-available="{esc(c["available"])}" data-error="{esc(c["error"])}" data-confirm="{esc(c["confirm"])}" data-updated="{esc(c["updated"])}" data-unverified="{esc(c["unverified"])}"><summary aria-label="{esc(c["update"])}" title="{esc(c["update"])}">{icon("update")}<span class="version">{VERSION}</span></summary><div class="panel-menu"><p>{esc(c["update"])} · v{VERSION}</p><p data-status role="status">{esc(c["checking"])}</p><button data-retry type="button">{esc(c["retry"])}</button><button data-apply type="button" hidden>{esc(c["apply"])}</button><noscript><p>{esc(c["error"])}</p></noscript></div></details>'
 f'<details class="panel mobile-panel"><summary aria-label="{esc(c["menu"])}">{icon("menu")}</summary><nav class="panel-menu mobile-nav" aria-label="{esc(c["menu"])}">{nav}</nav></details>')
 doclang={'en':'en','zh':'zh-Hans','ms':'ms'}[lang]
 return f'''<!doctype html>
<html lang="{doclang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="robots" content="noindex,nofollow"><meta name="pomelo-version" content="{VERSION}"><title>{esc(c['nav'][PAGES.index(page)])} | Pomelo STEM</title><script src="{ASSET}boot.js?v={VERSION}"></script><link rel="stylesheet" href="{ASSET}site.css?v={VERSION}"><script defer src="{ASSET}app.js?v={VERSION}"></script><script defer src="{ASSET}update.js?v={VERSION}"></script></head>
<body><div class="loader" aria-hidden="true"><div><img src="{ASSET}pomelo-compact.svg" alt=""><span>{esc(c['loading'])}</span></div></div><a class="skip" href="#main">{esc(c['skip'])}</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{link('index')}"><img src="{ASSET}pomelo-compact.svg" alt=""><span>POMELO STEM</span></a><nav class="desktop-nav" aria-label="{esc(c['menu'])}">{nav}</nav><div class="controls">{control}</div>{button(c['cta'],link('contact')) .replace('class="btn btn-primary"','class="btn btn-primary header-cta"')}</div></header>
<main id="main">{RENDERERS[page](c)}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="{link('index')}"><img src="{ASSET}pomelo-compact.svg" alt=""><span>POMELO STEM</span></a><p>{esc(c['tagline'])}</p></div><div><h3>{esc(c['solutions'])}</h3>{foot}</div><div><h3>{esc(c['company'])}</h3><a href="https://wa.me/601139023123">WhatsApp<br>+60 11-3902 3123</a><a href="https://pomelostem.com/">pomelostem.com</a></div></div><div class="footer-bottom"><span>© 2026 Pomelo STEM · Malaysia &amp; Singapore</span><span>{esc(c['footer_note'])}</span></div></div></footer></body></html>\n'''

def main():
 for lang in COPY:
  for page in PAGES:
   target=OUT / ('' if lang=='en' else lang) / (page+'.html')
   target.parent.mkdir(parents=True,exist_ok=True)
   target.write_text(render(lang,page),encoding='utf-8')
 print('Generated',len(COPY)*len(PAGES),'V7 pages')
if __name__=='__main__': main()
